<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$brands=$pdo->query('SELECT b.*,COUNT(p.id) product_count FROM brands b LEFT JOIN products p ON p.brand_id=b.id AND p.is_active=1 WHERE b.is_active=1 GROUP BY b.id ORDER BY b.is_featured DESC,b.name')->fetchAll();$pageTitle='Beauty Brands | Luméa Beauty';$pageDescription='Explore authentic beauty brands available at Luméa Beauty.';require __DIR__.'/includes/header.php';?>
<section class="page-title"><span class="eyebrow">AUTHENTIC BEAUTY</span><h1>Shop by Brand</h1><p>Discover trusted international and curated beauty names in one place.</p></section><section class="container" style="padding-bottom:70px"><div class="brand-directory"><?php foreach($brands as $b):?><a class="brand-directory-card" href="<?=url('/brand/'.$b['slug'])?>"><?php if($b['logo']):?><img src="<?=e(productImageUrl($b['logo']))?>" alt="<?=e($b['name'])?> logo"><?php else:?><span class="brand-letter"><?=e(mb_substr($b['name'],0,1))?></span><?php endif;?><h2><?=e($b['name'])?></h2><p><?=e($b['description']??'Curated beauty essentials.')?></p><small><?=number_format((int)$b['product_count'])?> products</small></a><?php endforeach;?></div></section><?php require __DIR__.'/includes/footer.php';?>
